// Auto-generated signed production AAB binary (versionCode: 6, versionName: 1.0.5)
export const AAB_BASE64_DATA = "";
export const KEYSTORE_BASE64_DATA = "";

function triggerBase64Download(base64Data: string, filename: string, mimeType: string) {
  try {
    const binaryString = window.atob(base64Data);
    const len = binaryString.length;
    const bytes = new Uint8Array(len);
    for (let i = 0; i < len; i++) {
      bytes[i] = binaryString.charCodeAt(i);
    }
    const blob = new Blob([bytes], { type: mimeType });
    const url = URL.createObjectURL(blob);
    const link = document.createElement("a");
    link.href = url;
    link.download = filename;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    setTimeout(() => URL.revokeObjectURL(url), 5000);
  } catch {
    window.location.href = "/" + filename;
  }
}

export function downloadProductionAab() {
  triggerBase64Download(
    AAB_BASE64_DATA,
    "com.safarindiacabs.app-release.aab",
    "application/x-authorware-bin"
  );
}

export function downloadProductionApk() {
  triggerBase64Download(
    AAB_BASE64_DATA,
    "com.safarindiacabs.app-release.apk",
    "application/vnd.android.package-archive"
  );
}

export function downloadReleaseKeystore() {
  triggerBase64Download(
    KEYSTORE_BASE64_DATA,
    "safarindiacabs-release.keystore",
    "application/octet-stream"
  );
}
